import {Ajv} from 'ajv';
import type {ValidateFunction} from 'ajv';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  validator?: ValidateFunction;
  execute: ToolExecutor;
}

export class ToolRegistry {
  private readonly ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});
  private readonly dynamicValidators = new WeakMap<object, ValidateFunction>();
  private readonly tools = new Map<string, StoredTool>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const validator = typeof definition === 'function' ? undefined : this.compile(resolved);
    this.tools.set(resolved.name, {definitionSource: definition, validator, execute});
  }

  private compile(definition: ToolDefinition): ValidateFunction {
    try {
      return this.ajv.compile(definition.inputSchema);
    } catch (error) {
      const reason = error instanceof Error ? error.message : 'unknown error';
      throw new Error(`Invalid inputSchema for tool ${definition.name}: ${reason}`, {cause: error});
    }
  }

  private validatorFor(tool: StoredTool): ValidateFunction {
    if (tool.validator) return tool.validator;
    const definition = this.resolveDefinition(tool.definitionSource);
    let validator = this.dynamicValidators.get(definition.inputSchema);
    if (!validator) {
      validator = this.compile(definition);
      this.dynamicValidators.set(definition.inputSchema, validator);
    }
    return validator;
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input against inputSchema before running; see specs/hal-engine-tool-input-validation/spec.md. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validate = this.validatorFor(tool);
    if (!validate(input)) {
      const problems = (validate.errors ?? []).map(e => {
        const path = e.instancePath || '/';
        if (e.keyword === 'required')
          return `${path === '/' ? '' : path}/${String(e.params.missingProperty)} is required`;
        if (e.keyword === 'type') return `${path} must be ${String(e.params.type)}`;
        return `${path} fails ${e.keyword} constraint`;
      });
      log.warn('tool', 'input rejected', {name, problems});
      return {result: `Invalid input for tool ${name}: ${problems.join('; ')}`};
    }
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

/** @type {import('ts-jest').JestConfigWithTsJest} */
export default {
  testEnvironment: 'node',
  roots: ['<rootDir>/src', '<rootDir>/scripts'],
  testMatch: ['**/*.test.ts'],
  // Fixture suites are inputs to the gate tests, not tests; one of them is deliberately skipped.
  testPathIgnorePatterns: ['/node_modules/', '/scripts/fixtures/'],
  extensionsToTreatAsEsm: ['.ts'],
  moduleFileExtensions: ['ts', 'js', 'json'],
  // NodeNext source writes `./x.js` for `./x.ts`; jest resolves the real file.
  moduleNameMapper: {
    '^(\\.{1,2}/.*)\\.js$': '$1',
  },
  transform: {
    '^.+\\.tsx?$': ['ts-jest', {useESM: true}],
  },
  // src/ only: the scripts/ suites drive their subjects through spawnSync, so an
  // instrumented .mjs would report zero regardless of how well it is tested.
  collectCoverageFrom: ['src/**/*.ts', '!src/**/*.test.ts', '!src/providers/providerTestSupport.ts'],
  // A ratchet, not a target: these are exactly what the suite measured when the
  // gate landed, so any drop fails and any rise should move them up with it. A
  // red run is fixed by adding the missing test, never by lowering the number
  // (specs/hal-engine-npm-release/spec.md).
  // The one exception: deleting covered code shrinks the denominator and lowers
  // the percentage while the uncovered count is unchanged. Compare covered/total
  // absolutes before re-baselining, and say so in the commit.
  // Per-path floors set at measurement, exactly as the global row is. An earlier version set them at
  // 70 with a comment claiming all four sat well above it - vertex's branches were 69.23, below it, and
  // four groups gained an 18-to-30 point regression budget the single global floor had never allowed.
  // `src/orchestration/tools/` is named separately because a path floor is a prefix match: without it a
  // regression in the tools registry hides inside the orchestration figure, which is what these exist
  // to prevent. Naming a path REMOVES its files from the `global` group, so the global numbers below
  // cover the remainder - the provider adapters and ws helpers with no suite - and are lower for that
  // reason rather than because coverage fell. Raise any of these with the measurement; never lower one
  // to go green (specs/hal-engine-npm-release/spec.md).
  // Only `branches` was re-measured on jest 30, which instruments branch points jest 29 never saw.
  // Across src/ the branch count went 240/350 covered to 332/473 while statements (665/842), functions
  // (180/226) and lines (601/756) are identical to the unit - the same 385 tests, none added, none
  // removed. No branch that was covered became uncovered, so a group whose percentage fell did so
  // because its denominator grew: vertex, mock and global rose, orchestration and its tools fell.
  // That is a finer instrument reading the same suite, which is why these two moved down.
  coverageThreshold: {
    'src/orchestration/': {statements: 88.3, branches: 80.85, functions: 92, lines: 87.91},
    'src/orchestration/tools/': {statements: 66.66, branches: 56.25, functions: 71.42, lines: 70.83},
    'src/infrastructure/stores/': {statements: 100, branches: 100, functions: 100, lines: 100},
    'src/providers/vertex/': {statements: 87.95, branches: 74.64, functions: 93.33, lines: 91.78},
    'src/providers/mock/': {statements: 100, branches: 78.57, functions: 100, lines: 100},
    global: {statements: 71.48, branches: 64.82, functions: 68.57, lines: 71.9},
  },
};

